function fakeFetchUser(id) {
  return new Promise(resolve => {
    setTimeout(() => resolve(`user-${id}`), 100 - id * 10);
  });
}

async function printUsers(ids) {
  ids.forEach(async (id) => {
    const user = await fakeFetchUser(id);
    console.log(user);
  });
  console.log('done looping');
}

printUsers([1, 2, 3]);

async function getTotalOrders(userIds) {
  let total = 0;
  for (const id of userIds) {
    const orders = await db.getOrders(id);
    total += orders.length;
  }
  return total;
}

exercises.solutionCode:
async function getTotalOrders(userIds) {
  const ordersPerUser = await Promise.all(
    userIds.map(id => db.getOrders(id))
  );
  return ordersPerUser.reduce((total, orders) => total + orders.length, 0);
}

sections.body:
When Node.js was created in 2009, JavaScript had no built-in module concept: no import, no standard way to split code across files and share values between them. Node solved this by inventing its own convention, now called **CommonJS**: every file is its own module, require('./math') synchronously loads and runs another file, and whatever that file attached to module.exports is what you get back.

```javascript
// math.js (CommonJS)
function add(a, b) { return a + b; }
module.exports = { add };

// app.js (CommonJS)
const { add } = require('./math');
console.log(add(2, 3));   // 5
```

JavaScript eventually got its own official module system, **ES Modules** (ESM), standardized in ES2015 (import/export) for browsers and the language rather than for Node alone. Node took several more years to support ESM (unflagged support landed around Node 12-13), by which time CommonJS underpinned an enormous package ecosystem, so Node ended up supporting both, permanently:

```javascript
// math.mjs (ES Module)
export function add(a, b) { return a + b; }

// app.mjs (ES Module)
import { add } from './math.mjs';
console.log(add(2, 3));   // 5
```

The syntax is the visible difference and the smaller one. The two systems differ in more fundamental ways, covered next, that can surface as errors rather than style choices.

Node decides which module system a .js file uses from the nearest package.json's "type" field: "type": "commonjs" (the default if the field is omitted) makes .js files CommonJS; "type": "module" makes them ESM. You can also force a specific file's system regardless of the package-level setting with the .cjs or .mjs extensions.

Switching a project to "type": "module" changes more than import syntax: several CommonJS-only globals don't exist in ESM files. require, module, exports, __dirname, and __filename are all undefined there, because they were never part of the language's module spec, only Node's CommonJS implementation. The classic ESM replacement for __dirname/__filename uses the standard import.meta.url with the url and path core modules:

```javascript
import { fileURLToPath } from 'url';
import path from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
```

Node 20.11 and later also provide import.meta.dirname and import.meta.filename directly, which makes the three-line idiom unnecessary on current versions.

Mixing the two systems in one project is supported but asymmetric, and the asymmetry is where errors come from. An ESM file **can** import a CommonJS module smoothly: Node treats the CJS module's module.exports as the default export. The other direction is more restricted. ESM loading is asynchronous by design, and require() is synchronous, so for most of Node's history a CommonJS file **could not** require() an ESM module: the attempt threw Error [ERR_REQUIRE_ESM]: require() of ES Module ... not supported. Node 22.12 and later (also backported to 20.19) can require() an ES module as long as neither it nor anything it imports uses top-level await; if one does, require() throws ERR_REQUIRE_ASYNC_MODULE. The approach that works on every version is the dynamic import('./thing.mjs') function, which returns a Promise, so you can't get a synchronous result back the way require gives you one.

examples.code:
// --- CommonJS: mathUtils.js ---
function square(n) {
  return n * n;
}
module.exports = { square };

// --- CommonJS: app.js ---
const { square } = require('./mathUtils');
console.log(square(4));   // 16


// --- ES Module: mathUtils.mjs ---
export function square(n) {
  return n * n;
}

// --- ES Module: app.mjs ---
import { square } from './mathUtils.mjs';
console.log(square(4));   // 16

// a.js
console.log('a.js starts');
module.exports.value = 1;
const b = require('./b');
console.log('a.js sees b.value =', b.value);
module.exports.value = 2;

// b.js
console.log('b.js starts');
module.exports.value = 10;
const a = require('./a');
console.log('b.js sees a.value =', a.value);   // 1, not 2: a.js isn't finished yet
module.exports.value = 20;

// main.js
const a = require('./a');
console.log('main.js sees a.value =', a.value);

// utils.mjs
import { fileURLToPath } from 'url';
import path from 'path';
import fs from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const configPath = path.join(__dirname, 'config.json');
const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
console.log(config);

